Use a `variant` union and Tailwind classes.

```tsx
type Variant = "primary" | "secondary";
type ButtonProps = { children: React.ReactNode; variant?: Variant };

export function Button({ children, variant = "primary" }: ButtonProps) {
  const cls = variant === "primary" ? "bg-blue-600 text-white" : "bg-gray-200";
  return <button className={`rounded px-4 py-2 ${cls}`}>{children}</button>;
}
```

The union keeps invalid variants out at compile time.

